  - die=d-0007 def=die_strike school=neutral risk=safe face=0 kind=purge value=1 label=刺击 1 corrupt=no
  - die=d-0009 def=skill_blade_flurry school=blade risk=safe face=2 kind=purge value=3 label=突刺 3 corrupt=no
slots(5):
  - slot=slot_1 kind=attack constraint=any effect=purge bonus=0 disabled=no
  - slot=slot_2 kind=attack constraint=ge:3 effect=purge bonus=1 disabled=no
  - slot=slot_3 kind=defense constraint=any effect=ward bonus=0 disabled=no
  - slot=slot_4 kind=heal constraint=even effect=mend bonus=1 disabled=no
  - slot=slot_5 kind=utility constraint=any effect=any bonus=0 disabled=no
enemies(2):
  - enemy=e-00 def=mon_verdant_slime school=verdant hp=7/7 ward=0 phase=1 taunt=自然 · 黏滑的腐殖体 status=- intent=kind=purge value=1 school=verdant arrow=down slot=e_slot_0
  - enemy=e-01 def=mon_arcana_wisp school=arcana hp=6/6 ward=0 phase=1 taunt=秘法 · 飘忽的咒火 status=- intent=kind=purge value=1 school=arcana arrow=up slot=e_slot_0
legal: discard_die,end_turn,play_face,use_ability
map:
  stage=1 row=1 node=n-01-1-0 path=[n-01-0-0,n-01-1-0]
  node=n-01-0-0 kind=battle visited=yes reachable=no edges=[n-01-1-0] preview=enemies=[腐生史莱姆] schools=[verdant] arrow=down
  node=n-01-0-1 kind=battle visited=no reachable=no edges=[n-01-1-0,n-01-1-1] preview=enemies=[腐生史莱姆,游荡咒火] schools=[verdant,arcana] arrow=down
  node=n-01-0-2 kind=battle visited=no reachable=no edges=[n-01-1-1] preview=enemies=[腐生史莱姆,游荡咒火] schools=[verdant,arcana] arrow=down
  node=n-01-1-0 kind=battle visited=yes reachable=no edges=[] preview=enemies=[腐生史莱姆,游荡咒火] schools=[verdant,arcana] arrow=down
